sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        // Validate required fields
        if (!current.collateral_case_id || !current.state) {
            gs.error('Missing required fields: collateral_case_id and state');
            return;
        }

        var caseId = current.collateral_case_id.getDisplayValue();
        //var state = current.state;

        // Defensive: Ensure caseId is a string
        if (typeof caseId !== 'string') {
            caseId = caseId.toString();
        }

        var treatsFlag = gs.getProperty("x_hsb11_mss_coll_0.Collateral_Treats_Switch").toString();
        var outcome = current.u_outcome;

        if (treatsFlag == "false" && current.state == 3 && (outcome == "Action required in Treats - Settmoves" || outcome == "Action required in Treats - Settmoves with New Settlement Date")) {
            return;
        }
        var grStateUpdate = new MSS_Record_Movement();
        grStateUpdate.updateStateCaseRecord(caseId);

        //gs.info("Update Case Record - State executed");

    } catch (e) {
        gs.error('Error in executeRule: ' + e.message);
    }
})(current, previous);
